static bool __io_eventfd_signal(struct io_ev_fd *ev_fd)
{
	/*
	 * Signaling the eventfd requires a regular spinlock, which can't be
	 * acquired while holding a raw spinlock (with IRQs disabled). Defer
	 * the signal to a safe context if we're in such a situation.
	 * eventfd_signal_allowed() checks for recursive signaling, and
	 * !irqs_disabled() ensures we're not holding a raw spinlock.
	 */
	if (eventfd_signal_allowed() && !irqs_disabled()) {
		eventfd_signal_mask(ev_fd->cq_ev_fd, EPOLL_URING_WAKE);
		return true;
	}

